--- 迷宫
local Singleton = import('Frame.Singleton')

local WaitForSeconds = CS.UnityEngine.WaitForSeconds
local GameObject = CS.UnityEngine.GameObject
local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
local CinemachineSmoothPath = CS.Cinemachine.CinemachineSmoothPath
local KTool = CS.Engine.Lib.KTool
local Animator = CS.UnityEngine.Animator

---@class WorldBossMgr
---@field GetInstance fun(self:WorldBossMgr):WorldBossMgr
local WorldBossMgr = Class("WorldBossMgr", Singleton)

function WorldBossMgr:__init()
    self._bossParGo = nil             --boss父节点
    self._bossPos = nil
    self._bossGo = nil
    self._cam = nil
end

function WorldBossMgr:__delete()
    self._bossParGo = nil             --boss父节点
    self._bossPos = nil
    self._bossGo = nil
    self._cam = nil
end

---Init
---初始化
function WorldBossMgr:Init()
    self._bossParGo = GameObject.Find("EnemyPath")
    if self._bossParGo then
        local cinemachineSmoothPath = self._bossParGo:GetComponent(typeof(CinemachineSmoothPath))
        if cinemachineSmoothPath then
            self._bossPos = cinemachineSmoothPath:EvaluatePosition(2)
        else
            self._bossPos = Vector3(0, 0, 0)
        end
    else
        self._bossPos = Vector3(0, 0, 0)
    end
end

--初始化boss
function WorldBossMgr:InitBossModel()
    if not self._bossGo then
        local bossVo = QuestConfMgr:GetInstance():GetWorldBossBossVo(worldBossComponent:GetCurBossPlanId())
        if bossVo then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(bossVo.skinId)
            if skinVo then
                local modelVo = CfUtils.GetCfVo(AutoIds.IdSetting274, "ModelVo", skinVo.mode)
                if modelVo then
                    local enemyPar = GameObject.Find("EnemyPath")
                    if enemyPar then
                        if IsNull(self.bossLoader) then
                            self.bossLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Arts/Prefab/" .. modelVo.modelRes .. ".prefab", nil, true)
                        end
                        if self.bossLoader.IsSuccess then
                            self._bossGo = CfUtils.InstantiateGo(self.bossLoader.ResultObject, enemyPar)
                        end
                        if self._bossGo then 
                            self._bossGo.transform.position = self._bossPos 
                        end
                    end
                end
            end
        end
    else
        KTool.SetActive(self._bossGo, true)
    end

    self._cam = KTool.FindCameraForLayer(CS.UnityEngine.LayerMask.NameToLayer("Default"))
    if self._cam then
        local ani = KTool.GetOrAddComponent(self._cam.gameObject, typeof(Animator))
        if ani then
            if IsNull(self.animLoader) then
                self.animLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("RuntimeController/WorldBossMainCamera.controller", nil, true)
            end
            local animCtrl
            if self.animLoader.IsSuccess then
                animCtrl = GameObject.Instantiate(self.animLoader.ResultObject)
            end
            if animCtrl then
                ani.runtimeAnimatorController = animCtrl
            end
        end
    end
    worldBossComponent._isShowAnimator = true
end

function WorldBossMgr:PlayAni(name)
    if not self._cam or not name then 
        return 0
    end
    self:SetCamCinema(false)
    local ani = KTool.GetOrAddComponent(self._cam.gameObject, typeof(Animator))
    ani:Play(name)
end

--删除boss
function WorldBossMgr:DestoryBossModel()
    if self._bossGo then
        --CS.UnityEngine.GameObject.Destroy(self._bossGo)
        if self._bossGo then
            KTool.SetActive(self._bossGo, false)
        end
    end
    if self._cam then
        local ani = KTool.GetComponent(self._cam.gameObject, typeof(Animator))
        if ani then
            CS.UnityEngine.GameObject.Destroy(ani)
        end
    end
end

--摄像机的cineam
function WorldBossMgr:SetCamCinema(isTrue)
    local cinema = KTool.GetComponent(self._cam.gameObject, typeof(CS.Cinemachine.CinemachineBrain))
    if cinema then
        cinema.enabled = isTrue
    end
end

function WorldBossMgr:Clear()
    if not isNull(self.animLoader) then
        self.animLoader:Release(true)
        self.animLoader = nil
    end
    if not isNull(self.bossLoader) then
        self.bossLoader:Release(true)
        self.bossLoader = nil
    end
    self:SetCamCinema(true)
    if self._cam then
        local ani = KTool.GetComponent(self._cam.gameObject, typeof(Animator))
        if ani then
            CS.UnityEngine.GameObject.Destroy(ani)
        end
    end

    self:__delete()
    self.Destroy(self)   --这个好像没用
end

return WorldBossMgr
